INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (1,'Arica — Aterrizaje Cable Submarino SAm-1','intercambia / recibe','0101000020E6100000CF7688C4A19351C0290D2AC92E7932C0',2069,0.0,'https://www.submarinecablemap.com/api/v3/landing-point/arica-chile.json','Estación de aterrizaje internacional en el extremo norte de Chile. Cable en servicio desde 2001: South America-1 (SAm-1), conectando Chile con Perú, Ecuador, Colombia y EE. UU.');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (2,'Antofagasta — Nodo Troncal Norte Grande','genera / recibe','0101000020E61000003D0AD7A3709951C066F7E461A1A637C0',2070,0.0,'https://www.subtel.gob.cl/wp-content/uploads/2018/12/resiliencia_uchile_corfo_subtel.pdf','Principal polo urbano, minero y de agregación de tráfico del Norte Grande sobre la columna vertebral Ruta 5 Norte documentada en el Estudio SUBTEL / NIC Labs (2018).');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (3,'La Serena / Coquimbo — Nodo Troncal Norte Chico','genera / recibe','0101000020E61000005F3A943E20D051C09B8087EB16E73DC0',576,4.41e-05,'https://www.subtel.gob.cl/wp-content/uploads/2018/12/resiliencia_uchile_corfo_subtel.pdf','Capital de la Región de Coquimbo y punto troncal intermedio del corredor Norte Chico hacia Santiago (componente SAIP continua de 178 vértices hasta Quilicura).');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (4,'Valparaíso — Aterrizaje Cables Submarinos SAm-1 / SAC','intercambia / recibe','0101000020E61000000860D4F3B5E751C0421955A5DB8540C0',2071,0.0,'https://www.submarinecablemap.com/api/v3/landing-point/valparaso-chile.json','Principal puerta internacional de Chile en el Pacífico. Cables en servicio antes de 2010: South American Crossing (SAC, 2000) y South America-1 (SAm-1, 2001); ciudad con anillo urbano citado en el Estudio SUBTEL (2018, p. 22).');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (5,'Santiago — Cirion SAN1 (PIT Chile / Data Center)','genera / intercambia / recibe','0101000020E6100000F3E505D847AB51C094A12AA6D2AD40C0',2072,0.0,'https://www.peeringdb.com/fac/2093','Principal instalación de colocation e intercambio de tráfico en Chile (registrada en PeeringDB antes de 2019; 70 redes y 4 IXP declarados). Articula la entrada norte del Gran Santiago.');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (6,'Santiago — Entel CNT / Torre Entel (PIT / Troncal)','genera / intercambia / recibe','0101000020E6100000ECC1A4F8F8A951C021956247E3B840C0',2074,0.0,'https://www.peeringdb.com/fac/5301','Centro neurálgico histórico de telecomunicaciones de Chile (registrado en PeeringDB antes de 2019; 10 redes y 2 IXP). Concentra interconexión nacional y salida troncal sur.');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (7,'Santiago — Equinix ST1/ST2 (Data Center / IXP)','genera / intercambia / recibe','0101000020E6100000ECA694D74AB651C0BBF1EEC858B940C0',2073,0.0,'https://www.peeringdb.com/fac/5295','Data center de interconexión y alojamiento de contenido en el sector poniente de Santiago (PeeringDB < 2019; 11 redes y 2 IXP). Articula el acceso desde Valparaíso por Ruta 68.');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (8,'Rancagua — Nodo Troncal O''Higgins','genera / recibe','0101000020E6100000DE9387855AAF51C012143FC6DC1541C0',2075,0.0,'https://www.subtel.gob.cl/wp-content/uploads/2018/12/resiliencia_uchile_corfo_subtel.pdf','Capital de la Región de O''Higgins y primer nodo troncal al sur de Santiago sobre la Ruta 5 Sur en el levantamiento SAIP / Estudio SUBTEL (2018).');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (9,'Talca — Nodo Troncal Región del Maule','genera / recibe','0101000020E61000001973D712F2E951C0D881734694B641C0',2076,0.0,'https://www.subtel.gob.cl/wp-content/uploads/2018/12/resiliencia_uchile_corfo_subtel.pdf','Capital de la Región del Maule y nodo troncal central ubicado en la zona epicentral del terremoto del 27F (a ~137 km del epicentro USGS).');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (10,'Concepción — Nodo Troncal Biobío / REUNA','genera / intercambia / recibe','0101000020E610000050FC1873D74252C08CB96B09F96842C0',2077,0.0,'https://www.subtel.gob.cl/wp-content/uploads/2018/12/resiliencia_uchile_corfo_subtel.pdf','Segundo polo metropolitano del país, sede regional de intercambio académico (REUNA) y anillo urbano de fibra soterrada citado en el Estudio SUBTEL (2018, p. 22). Zona de máximo impacto del 27F (~79 km del epicentro).');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (11,'Temuco — Nodo Troncal La Araucanía','genera / recibe','0101000020E6100000BDE3141DC92552C02E90A0F8315E43C0',2078,0.0,'https://www.subtel.gob.cl/wp-content/uploads/2018/12/resiliencia_uchile_corfo_subtel.pdf','Capital de la Región de La Araucanía y una de las cuatro ciudades principales con anillo urbano de fibra soterrada citadas en el Estudio SUBTEL (2018, p. 22).');
INSERT INTO resiliencia."key_nodes" ("id","name","role","geom","vertex_id","snap_distance_m","reference","justification") VALUES (12,'Puerto Montt — Nodo Troncal Los Lagos (Puerta Austral)','genera / intercambia / recibe','0101000020E610000007F01648503C52C0A301BC0512BC44C0',2079,0.0,'https://www.subtel.gob.cl/wp-content/uploads/2018/12/resiliencia_uchile_corfo_subtel.pdf','Capital de la Región de Los Lagos y nodo articulador del tráfico troncal entre Chile central y la macrozona sur-austral (Estudio SUBTEL 2018).');
